];

export function LanguageSwitcher() {
    const {lang, setLang, t} = useAppLang();

    return (
        <SegmentedRadioGroup<AppLang>
            aria-label={t('app', 'label_language-switcher')}
            value={lang}
            onUpdate={setLang}
            options={LANG_OPTIONS}
        />
    );
}
